import{_ as t,c as n,o,ag as a}from"./chunks/framework.Bzez9NG9.js";const s="/space/img/space-settings.png",i="/space/img/my_environments.png",r="/space/img/edit_environment.png",A=JSON.parse('{"title":"Configuration","description":"Configure SPACE connections, access, content, AI, jobs, system settings, server health, and activity, and manage PAW extension environment mappings when applicable.","frontmatter":{"title":"Configuration","description":"Configure SPACE connections, access, content, AI, jobs, system settings, server health, and activity, and manage PAW extension environment mappings when applicable.","keywords":["SPACE configuration","SPACE settings","connections","access","AI profiles","jobs","system settings","My environments","extension setup","PAW"],"outline":"deep"},"headers":[],"relativePath":"doc/configuration/index.md","filePath":"doc/configuration/index.md"}'),d={name:"doc/configuration/index.md"};function c(l,e,p,h,g,m){return o(),n("div",null,e[0]||(e[0]=[a('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>SPACE settings control how a SPACE instance connects to external systems, who can use it, how shared content is maintained, how AI is configured, and how scheduled and operational tasks are managed.</p><p>Administrators can open the SPACE sidebar and click the <strong>Settings</strong> icon to access the shared SPACE configuration areas. The Settings icon is shown only to admin users.</p><p><img src="'+s+'" alt="SPACE settings" data-zoomable=""></p><h2 id="configuration-areas" tabindex="-1">Configuration areas <a class="header-anchor" href="#configuration-areas" aria-label="Permalink to &quot;Configuration areas&quot;">​</a></h2><p>The settings are organized by responsibility so administrators can move directly to the part of SPACE they need to manage.</p><table tabindex="0"><thead><tr><th>Settings area</th><th>What it manages</th></tr></thead><tbody><tr><td><a href="./connections/">Connections</a></td><td>IBM Planning Analytics and supported external data connections, authentication, job credentials, and connection access.</td></tr><tr><td><a href="./access.html">Access</a></td><td>SPACE users, invitations, access tokens, roles, secrets and platform access.</td></tr><tr><td><a href="./content.html">Content</a></td><td>Cached model documentation and logs, manual updates, retention, and exports.</td></tr><tr><td><a href="./system-settings.html">Configuration</a></td><td>System-wide settings for logging, synchronization, uploads, Python packages, model search, and other platform behavior.</td></tr><tr><td><a href="./ai.html">AI</a></td><td>AI profiles, providers, models, and response settings.</td></tr><tr><td><a href="./jobs.html">Jobs</a></td><td>Scheduled model documentation and log updates, Python scripts, TM1 Git synchronization, and other automated tasks.</td></tr><tr><td><a href="./journal.html">Journal</a></td><td>SPACE activity records, execution details, filtering, and exports.</td></tr><tr><td><a href="./server.html">Server</a></td><td>SPACE service resource usage and infrastructure health.</td></tr></tbody></table><p>A typical setup starts with <strong>Connections</strong> and <strong>Access</strong>, followed by any required <strong>AI</strong>, <strong>Content</strong>, <strong>Jobs</strong>, and system-level configuration.</p><h2 id="paw-environments" tabindex="-1">PAW environments <a class="header-anchor" href="#paw-environments" aria-label="Permalink to &quot;PAW environments&quot;">​</a></h2><blockquote><p><strong>Available only when using the SPACE extension with IBM Planning Analytics Workspace (PAW).</strong></p></blockquote><p><strong>PAW environments</strong> contains the personal mappings used by the SPACE browser extension. It identifies the PAW environments where the extension is enabled and maps each PAW URL to the appropriate SPACE host and personal SPACE access token.</p><p>These mappings are not required when using the standalone SPACE web application.</p><p>A client can use one SPACE instance with multiple IBM Planning Analytics environments, so several PAW URLs can map to the same SPACE host. These personal extension mappings are separate from the shared server connections configured under <a href="./connections/">Connections</a>.</p><p>When using SPACE inside PAW, open the <strong>user menu</strong> and select <strong>PAW environments</strong> to view or manage your mappings. This option is available to extension users independently of the admin-only SPACE settings.</p><p><img src="'+i+'" alt="My environments table" data-zoomable=""></p><p>Each row identifies a PAW environment and its mapped SPACE host. Select a row to edit or delete it, or use <strong>Refresh</strong> to reload the list. Changes apply only to your personal extension configuration.</p><h3 id="adding-or-editing-a-paw-environment" tabindex="-1">Adding or editing a PAW environment <a class="header-anchor" href="#adding-or-editing-a-paw-environment" aria-label="Permalink to &quot;Adding or editing a PAW environment&quot;">​</a></h3><p>Click <strong>New environment</strong>, or open an existing row, to edit the mapping.</p><p><img src="'+r+'" alt="Environment form" data-zoomable=""></p><p>Provide:</p><ul><li><strong>Name</strong> – label shown in the environment selector.</li><li><strong>IBM PA host</strong> – the PAW host where the SPACE extension is used, for example <code>spaceprod.planning-analytics.ibmcloud.com</code>.</li><li><strong>SPACE host</strong> – the SPACE server URL associated with that PAW environment.</li><li><strong>Access token</strong> – your personal SPACE access token. Use the eye icon to verify it before saving.</li></ul><p>Save the record, then refresh the environments list to confirm the updated mapping.</p>',22)]))}const f=t(d,[["render",c]]);export{A as __pageData,f as default};
